        "desc": "- 导语 -\n护照、签证，作为今日跨境迁移中常见的身份与准入凭证，往往被视为理所当然的存在。在历史学家麦基翁看来，现代意义上的「自由移民」并非天然自由，而是在国家权力的甄别与规训中形成。19世纪末至20世纪初，大量华人移民进入美国，并参与塑造了后来逐渐扩散至全球的移民管控制度。美国「排华法案」如何确立了移入国对移民的单方面管辖权？边境管控又如何反过来塑造华侨的国籍与民族认同？从比较研究到全球史，青年学者该如何面对「麦基翁难题」的两难抉择？请听本期嘉宾杨斌老师带来的精彩分享！\n- 本期话题成员 -\n程衍樑（微博@GrenadierGuard2）\n杨斌，香港城市大学历史系教授。著有《全球史的九炷香》《人海之间》《海贝与贝币》等。\n- 时间轴 -\n13:23 从常春藤正教授辞职：麦基翁对学术官僚体制的厌弃\n16:32 华人移民如何参与塑造美国海关与移民管控制度\n19:25 福柯的微观权力观：权力如何在签证与证明材料中运行\n29:00 美国移民管控的吊诡：非法移民相对容易，合法移民相对艰难\n30:18 移民制度为何是一种「忧郁的秩序」？\n33:53 废奴运动与契约劳工：「卖猪仔」现象的全球史背景\n38:02 先有护照，再有身份证：边境管控对华侨民族主义的反向塑造\n42:16 语言测试与经济原则：大英帝国殖民地如何自主筛选移民\n54:08 张爱玲笔下的南洋华侨女性\n56:49 麦基翁的跨国家庭：妻子是中国移民、收养中国女孩\n01:00:02 大数据时代，自由移民与主权国家的未解张力\n01:02:48 比较研究还是全球史研究：青年学者的「麦基翁难题」\n- 支持我们的赞助商是对我们最好的支持 -\n忽左忽右旅行团又要出发了！这一次，我们将前往坦桑尼亚，在乞力马扎罗山脚下开启东非之旅，探访塔兰吉雷、恩戈罗恩戈罗和塞伦盖蒂，感受东非野生世界的壮阔。再前往桑给巴尔，在石头城与印度洋海岸放慢脚步。本次坦桑尼亚行动，程衍樑将与一位首次参加忽左忽右旅行团的神秘嘉宾共同带队。2026年9月30日至10月11日，如果您有兴趣参与本次坦桑尼亚行动，请关注「忽左忽右leftright」公众号，回复「坦桑尼亚」了解详情，也可以直接添加旅行团小助手微信 hzhyxzs2 咨询报名。\n《忽左忽右》的卖书业务上线了！这次不仅汇集了节目中深入讨论过的书籍，还有主播个人精选书籍，含少量签名版及稀有原版，完整的书目信息及购买方式，前往微信公众号「忽左忽右leftright」，回复「买书」 即可获取。书目将不定期更新，欢迎常来看看。\n- 制作团队 -\n声音设计 hotair\n节目统筹 禾放\n节目运营 小米粒\n节目制作 思钊 Yo\nlogo设计 杨文骥\n- 音乐 -\nDanse Macabre - Busy Strings - Kevin MacLeod\n- 本节目由JustPod出品 © 2026 上海斛律网络科技有限公司 -\n\n- 互动方式 -\n商务合作：ad@justpod.fm\n微博：@忽左忽右leftright @播客一下 @JustPod\n微信公众号：忽左忽右Leftright / JustPod / 播客一下\n小红书：JustPod气氛组 / 忽左忽右\nB站：忽左忽右leftright\n抖音：忽左忽右",
