        "desc": "这一期节目，我想和你聊聊「审美」。\n过去两年，我越来越意识到，审美从来不只是关于穿衣风格、家居和品味，它更像是一种主体性的表达，是一个人精神世界的倒影，和内在秩序的延伸。\n这一期节目将不局限于传统意义上的“穿搭”或“变美”，而是从更深层的角度，探讨：\n为什么很多人始终找不到真正属于自己的审美坐标\n\n为什么越追逐潮流，反而越容易失去自我\n\n审美如何反应着一个人的生命状态、感知力与世界观\n\n建立属于自己的审美体系后，消费观和生活方式会有哪些变化\n\n本期节目由 【 唯品会】 和自我进化论共同呈现，上唯品会，穿得好，花得少。\n✨ 高光时刻 \n04:01 为什么很多人觉得自己没有审美？\n07:18 一个反直觉发现：放弃追逐审美后，审美反而长出来了\n10:03 是什么让乔布斯与安藤忠雄的审美如此与众不同？\n12:42 审美是一个人内在秩序的外化，也是人生哲学的投射\n15:04 我的审美公式：生命状态 ✖️ 感知力 ✖️ 世界观\n17:00 生命状态：决定审美的底层框架\n18:15 从追求刺激到欣赏留白：我的审美变化史\n24:03 感知力：决定审美的细腻程度\n30:04 敏感不是缺点，而是打开爱与美的基础能力\n32:38 世界观：决定审美最终的方向\n35:39 中国哲学与东方智慧如何改变了我的审美\n38:19 审美成熟后，我的消费观发生了什么变化？\n43:58 《邮差》：审美最终改变的，是看世界的眼睛\n👇关于唯品会 \n最近在整理衣橱、重新思考审美的过程中，我越来越认同唯品会倡导的理念——【穿得好，花得少】。\n穿得好，不只是追求品牌，而是选择真正适合自己的好设计、好面料和好品质；\n花得少，也不是一味省钱，而是不再为过度溢价买单，用更合理的价格买到真正喜欢、能够长期陪伴自己的东西。\n如果你也有同样的需求或好奇，不妨趁着现在年中特卖节， 上唯品会搜索【穿得好】 ，找到那些真正适合自己的物品。\n🎵 本期配乐 \n《Buscándote》- Osvaldo Fresedo\n🍃 关于《自我进化论》 \n《自我进化论》是一档由颜晓静创作，持续分享「自我探索」和「自我养育」内容的播客。欢迎在小宇宙、苹果播客、网易云音乐和喜马拉雅等平台订阅，全平台同步更新中。\n小红书官方账号： 自我进化论播客 \n抖音/视频号官方账号：自我进化论播客",
        "pub": "Fri, 12 Jun 2026 12:00:00 GMT",
        "link": "https://www.xiaoyuzhoufm.com/episode/6a2ba6a44233e62bc54898f7?utm_source=rss",
        "core": "本期《自我进化论》围绕「审美的尽头，是成为自己」展开。关注自我成长与心理疗愈，把抽象的成长命题拆成可落地的小练习，延续节目一贯的深度与质感。",
