        "desc": "今天的嘉宾，是“最受欢迎”返场的小花，宋佳。\n相隔两年再录播客，我们聊天的关键词，从“大女主”，悄然滑向了“命运”、“觉察”和“感受”。我们不再热衷于向外索求答案，而是向内探索那个“为什么是我？”以及“我为什么是现在的我？”的命题。我们都认同，诚实面对自己的起心动念，是抵达内心平静的第一步，因为“善语结善缘”，语言和本心始终有改变人的力量。从“我要我认为的”，到“一切都是最好的安排”，我们在人生的进程中有许多观点的转变，但最重要的是，我们不再执着于做命运的解题者，而是乐得成为一个体验者。\n01:34 宋佳聊自我变化——“希望忙着去做一些不忙的事情”\n03:42 诚实地面对自己的欲望，让“宇宙”不再“困惑”你到底要不要\n05:36 “善语结善缘”：语言发出的瞬间会定义你是怎样的人\n07:53 对抗与惯性：我们的很多反应，其实是被无意识掩盖了\n09:44 如果命运的剧本可以选择，为什么人会走向不同的人生？\n12:58 “事情本身，比是不是由你做成的更重要”\n16:04 宋佳的气味创作法：林慧（角色）是“水果腐烂前的奇异香气”\n19:22 在线计划旅行——热衷做计划的人，和等待被召唤的人\n23:45 杨天真：我会主动修正“急促感”带给周遭的压力场\n28:05 艺人的职业里，做演员和做明星，有感受上的不同吗？\n29:02 亲密关系中的相处：试图改变别人，是最大的痛苦\n31:30 宋佳：“执念”也是一种傲慢，我时刻希望自己保持清醒\n43:04 情绪价值的真谛——不是讨好，是“看见”\n46:45 关于社交，深度朋友在于生命能量的同频\n49:14 杨天真：对谈是在两个人在地球上一小时交互中迸发的真实状态的记录\n55:29 面对他者的羞辱，是否要为了尊严自证？\nBGM：《Doomed》\n\n/关于《杨天真的高情商公式》/ \n高情商=满足自己＋成全别人=成事\n我的高情商课程 总结了我过去工作和生活中高情商成事儿的实践经验，28节音频课，从底层认识到行动，教大家成为不仅让自己爽，还能成事儿的人。",
