        "full": "【开场】\n本期《无人知晓》带来「人何以自处」。一档值得关注的播客。\n\n【本期内容叙述】\n本期《无人知晓》播出「人何以自处」。节目延续一贯风格，围绕这一主题层层展开。\n▸ 我和李继刚聊了三个多小时。\n▸ 他有一个我很喜欢的判断：工业革命拿走了体力，AI 正在拿走脑力。 留给人的，是心力。\n▸ 不是你知道什么，而是你想要什么。不是你能想出什么，而是你能感受到什么。\n▸ 我们聊了 AI 时代的阅读、表达和教育，聊了信息输入如何塑造一个人的命运。\n▸ 他从理性的尽头走向心灵，我从心灵出发走向结构，但所有话题，最终都指向同一个问题：\n▸ 人何以自处？\n▸ 点此访问有知有行官网，获取完整文稿区内容。\n▸ 道也好，真理也罢——我们每个人只是在拿着自己的取景框看它\n\n节目没有停留在表面的观点罗列，而是在具体的情境、对话与追问中，把话题真正推进到深处。\n\n【🗣️ 经典对话】\n这一期里，有些话值得反复听：\n\n“ 我在（I am） ”\n“ 它在（It is） ”\n\n【深度解读】\n本期主题：「人何以自处」。本期主题：「人何以自处」。本期《无人知晓》围绕「人何以自处」展开。一档值得关注的播客，延续节目一贯的深度与质感。\n\n【核心看点】\n• 当期重点：♾️ 大家好，欢迎来到「无人知晓」，我是孟岩。这期节目，我和李继刚聊了三个多小时。\n\n【为什么值得听】\n延续《无人知晓》一贯的内容水准，值得点开收听完整内容。\n\n【结尾】\n延续《无人知晓》一贯的内容水准，值得点开收听完整内容。",
