        "desc": "日本杂谈之日本医疗体系拆解第三弹，聊一聊关于日本体检的那些事。\n大家好，我是大卫翁，\"起朱楼宴宾客\"是我用来记录这个大时代的播客节目。\n这个系列的前两期分别是《 vol.120.日本医疗体系的崩溃与重生：医院、药品、医保三角困局的一种解法 》和《 147.再谈日本医疗与照护行业之我曾在北海道的医院当护士 》，第三期我想借着在日本参加了一次免费健诊的契机来聊一下日本的体检系统的前世今生，以及日本的医保体系为什么要资助这种免费体检项目。\n简明时间轴：\n第一部分 日本的体检体系 \n参考资料：《総合健診・人間ドック草創期からの歴史に学ぶ精度管理の重要性》\n04:19 我在横滨参加免费体检的来龙去脉\n12:37 日本体检产业的历史\n22:45 为什么小诊所们愿意参与免费健诊体系？\n25:58 人間ドック是不是暴利？\n第二部分 日本的医保体系与体检的关系 \n参考资料： 《諸外国との比較による日本の医療保険制度の在り方》 \n《Positive Impact of Health Check-Ups and Guidance in the General Population》\n30:58 芬兰、美国和日本不同的医保制度决定了对于体检的不同态度\n37:17 日本预防医疗和医保体系本身挂钩的全过程\n51:55 医保支援下的体检到底有没有效果？\n第三部分 生活习惯病与体检的关系 \n参考资料：《 China launches National Obesity Campaign 》\n《Toward a Healthy and Harmonious Life in China》\n59:40 生活习惯病概念的来由\n69:53 中国的《体重管理年三年行动实施方案》和《国民健康\"十五五\"规划》说了什么\n欢迎关注我的新书《资产配置行动指南》，解读和购买链接在这里： 158. 播客里聊了四年的资产配置，我把它做成了一本《行动指南》 \n欢迎订阅我的Substack频道，它是一个以英文为主的频道： hubris2025.substack.com \n欢迎关注我和雨白、小跑新制作的时事聊天节目 《不熄灯Lights On》 \n欢迎关注我的生活方式类节目《犬生活》， 《纽约有一种气质叫“都行”｜和杨蒙恩的临别闲聊局》 最新上线！\n欢迎加入我的 知识星球 ，我正在好好运营那一片后花园。\n欢迎在评论区互动，或者给我写邮件，邮箱地址qizhulouyanbinke@gmail.com。\n节目BGM：\nJodymoon - the long way around\n白色巨塔主题曲《アメイジング・グレイス》\n节目后期：大卫翁",
