        "desc": "小海初中被迫辍学，漫长的打工岁月里，辗转于全国各地工厂，在枯燥的车间里，摇滚乐、古典诗词与海子的诗歌成为他的精神寄托，劳作间隙，他不停写下诗歌与歌词。他曾给自己崇拜的音乐人私信，只有张楚给予回应，这份鼓励推动他奔赴北京追梦。可是刚到北京的他居无定所，流浪街头，之后落脚皮村，运营公益二手衣物店，也就是大家熟知的 “诗歌商店”。多年坚持创作后，他的诗集正式出版，也站上海外的文学舞台，不过物质生活依旧清贫，还要直面爱情婚姻带来的现实重担。一路走来，唯一不变的就是他的真诚，节目中他的真诚打动了小寒老师和划水怪，也希望这份真诚，能戳中听节目的你们～\n\n更多精彩内容，欢迎收听本期节目~\n\n主播 / 相征 郭小寒\n\n嘉宾 / 小海\n\n音频后期 / 陆凯BBBBUDDHA\n\n音频上传 / 恬恬\n\n-本节目由深夜谈谈 Midnight Network出品 -\n\nTimeline: \n\n00:00:29 打破传说中的“不可能三角”！\n\n00:07:37 辍学南下：火车上的“痛感”与黑大巴惊魂\n\n00:11:26 车间里的那首《蓝莲花》\n\n00:20:56 踩着缝纫机背唐诗\n\n00:36:24 痴迷艾伦·金斯伯格的《嚎叫》\n\n00:45:48 追梦的“苦旅”\n\n00:53:27 没有文学、诗歌和摇滚乐，我将被淹没\n\n01:00:22 蚊子多得像盖了一层被子\n\n01:13:45 穿二手的衣服，读一流的诗\n\n01:32:46 从工厂流水线到柏林剧场\n\n01:41:58 当孙悟空变成西西弗斯\n\n02:06:37 一地鸡毛的生活里也有波澜壮阔\n\n02:10:57 The Doors - Riders on the Storm\n\n今年十一长假，由划水怪&amp;miya带队，七天六晚带你深入越后妻有和轻井泽。这片藏在日本新潟县的雪国山谷，是全世界独一无二的大地艺术祭现场。这次，不仅是一场艺术盛宴，更是一场舌尖之旅——从品尝当地新米到品鉴小诸威士忌，从妻有猪到和牛铁板烧，从药汤温泉到轻井泽骑行，吃喝玩乐一举拿下！名额有限，详情可进入微信小程序“大内夜市”查看。\n\n恰逢周年，大内十三周年限定主题周边正式上线。在香港的俚语里，“My Cup Of Tea”代表合心我意、投缘，于是我们将Tea替换成T恤的缩写Tee，于是就有了“MY CUP OF TEE 係我杯茶”的周年主题。而本次周边分为是定制马克杯、主题T恤两款单品，也推出了成套纪念礼盒（礼盒附赠随机主播签名嗷）～\n\n藏式金刚断烦恼，紫檀咒珠守心安。二十八宿催红鸾，甲子莲蓬伴流年。大内上新四款手串，愿你遇事不慌，少些内耗，遇见真心，白首不离。微信搜索小程序“大内夜市”，把祝福戴在腕间，日子自有光亮。\n\n深夜谈谈招聘啦，本次开放岗位\n\n全职：1、视频编导（北京/上海）&nbsp;2、商务BD&amp;AE （上海）\n\n感兴趣的朋友们请发送求职信+简历+个人作品请发送至邮箱jobs@midnightalks.com\n\n-你还可以在这里找到我们：\n\n小红书：@深夜谈谈、@相征terry、 @miya\n\nB站：@大内密谈midnightalks\n\n视频号&amp;抖音：@深夜谈谈\n\n微博：@大内密谈\n\n微信公众号：大内密谈\n\n商务合作邮箱：biz@midnightalks.com\n\n加听众群：加深夜谈谈子微信（微信号:SYTT-midnightalks2）并回复【听众群】即可进群。",
