        "full": "【开场】\n本期《大内密探》带来「在流水线写诗的少年 戳破了我最精致的泡沫」。一档值得关注的播客。\n\n【本期内容叙述】\n本期《大内密探》播出「在流水线写诗的少年 戳破了我最精致的泡沫」。节目延续一贯风格，围绕这一主题层层展开。\n▸ 主播 / 相征 郭小寒\n▸ 嘉宾 / 小海\n▸ 音频后期 / 陆凯BBBBUDDHA\n▸ 音频上传 / 恬恬\n▸ 打破传说中的“不可能三角”！\n▸ 辍学南下：火车上的“痛感”与黑大巴惊魂\n▸ 车间里的那首《蓝莲花》\n▸ 踩着缝纫机背唐诗\n\n节目没有停留在表面的观点罗列，而是在具体的情境、对话与追问中，把话题真正推进到深处。\n\n【🗣️ 经典对话】\n这一期里，有些话值得反复听：\n\n“My Cup Of Tea”\n“MY CUP OF TEE 係我杯茶”\n\n【深度解读】\n本期主题：「在流水线写诗的少年 戳破了我最精致的泡沫」。本期主题：「在流水线写诗的少年 戳破了我最精致的泡沫」。本期《大内密探》围绕「在流水线写诗的少年 戳破了我最精致的泡沫」展开。一档值得关注的播客，延续节目一贯的深度与质感。\n\n【核心看点】\n• 当期重点：小海初中被迫辍学，漫长的打工岁月里，辗转于全国各地工厂，在枯燥的车间里，摇滚乐、古典诗词与海子的诗歌成为他的精神寄托，劳作间隙，他不停写下诗歌与歌词。他曾给自己崇拜的音乐人私信，只有张楚给予回应，这份鼓励推动他奔赴北京追梦。\n\n【为什么值得听】\n延续《大内密探》一贯的内容水准，值得点开收听完整内容。\n\n【结尾】\n延续《大内密探》一贯的内容水准，值得点开收听完整内容。",
