            "passage": "昆明的雨，一下就是好几天。雨不大，可下得密，像把整个城市罩在一层薄纱里。院子里的缅桂花被雨洗过，香气比平时浓了一倍，甜得有点发腻。卖杨梅的苗族女人，戴着竹笠，背着竹篓，从巷子口慢慢走过——竹篓上盖着芭蕉叶，雨打不进去，里面是紫得发黑的杨梅，一颗颗滚圆，像眼睛。我小时候不爱撑伞，就那么淋着，从巷头走到巷尾。看雨从屋檐滴下来，在青石板上砸出小水花；看卖杨梅的女人走过去，再走过去。昆明的雨不催人，不紧不慢，是让你慢慢走，慢慢看的。",
