            "p": "情绪处理到最后，最有营养的一步是复盘：这一次，它想教会我什么？是某个人触碰到了我的某个旧伤口？还是我最近太累了，身体在喊停？把这件「想教会你的事」写下来。下次同样的情绪来时，你就有了准备——不再被它绑架，而能温和地认出它：哦，又是你。这次我能更好地处理你。这不是阿 Q 式的自我安慰，是一种非常成熟的心理能力——把情绪当作信号来读，而不是当敌人来打。情绪背后总有一个或多个未被满足的需求：被看见、被认可、被尊重、被爱、有空间。读懂那个需求，比消灭那个情绪，对生活更有用。半年后回看，你会发现自己情绪上头的频率明显下降，因为你已经学会了在它发生之前就接住它。"
