      {
        "id": "cls-014",
        "title": "登幽州台歌",
        "poet": "陈子昂",
        "era": "初唐 · 公元 696 年",
        "kind": "七言歌行 · 孤独的绝唱",
        "tags": [
          "前不见古人",
          "宇宙意识"
        ],
        "original": "前不见古人，后不见来者。\n念天地之悠悠，独怆然而涕下。",
        "translation": "向前看，看不见古时候那些贤人；\n向后看，看不见未来那些来者。\n想到天地之间无穷无尽，唯独我一个人，感到悲从中来，泪流满面。",
        "history": "陈子昂（659—700），梓州射洪（今四川射洪）人，是初唐诗文革新的旗手。他反对齐梁以来的'宫体诗'，主张恢复'汉魏风骨'——诗歌应该写'真感情'，不该写'宫廷艳情'。\n\n公元 696 年，他 38 岁，随武攸宜（武则天的侄子）北征契丹。他多次献策不被采纳，反而被降职。一天，他登上蓟北楼（即幽州台，故址在今北京一带），向北眺望，想到燕昭王当年在此筑黄金台招揽乐毅、剧辛等贤才的往事，而自己空有报国之志却无人赏识。\n\n他写下这首 22 个字的歌——'前不见古人，后不见来者'——成为中国诗里'孤独'的代名词。\n\n它对后世影响巨大：李白'登临'诗的'宇宙意识'、陈子昂此诗是源头。",
        "appreciation": "这 22 字是'孤独'的极简公式——'前不见古人'是'历史之孤'（回望不见前贤），'后不见来者'是'未来之孤'（前瞻不见后来人）。他被'夹'在中间——所有'古'和'来'都和我没关系。这种'四顾无人'的孤独，比'我不被理解'更绝望。\n\n'念天地之悠悠，独怆然而涕下'——'悠悠'二字是灵魂：天地为什么是'悠悠'的？因为'长'。当一个人想到'天地那么长，而我没有'，他才会真的哭。\n\n它教会我们：写'孤独'，不要写'没人懂我'。写'时间'——'在我之前/在我之后'。让'时间的厚度'承担'我的一瞬'。",
        "prompt": "写你'站在一个地方，前面/后面都没有人'的瞬间（深夜/山巅/旧城/地铁末班车），不写'我孤独'，只写'我之前是什么时代/我之后会是什么时代'，让'时间'承担你。"
      },
      {
        "id": "cls-015",
        "title": "木兰花·拟古决绝词",
        "poet": "纳兰性德",
        "era": "清 · 公元 1693 年前后",
        "kind": "词 · 满清第一词人",
        "tags": [
          "人生若只如初见",
          "决绝"
        ],
        "original": "人生若只如初见，何事秋风悲画扇。\n等闲变却故人心，却道故心人易变。\n骊山语罢清宵半，泪雨霖铃终不怨。\n何如薄幸锦衣郎，比翼连枝当日愿。",
        "translation": "人生如果都像初次相遇那般美好，该有多好；可偏偏像秋风中被人遗弃的画扇。\n轻易就变了心的，是从前的'那个人'——可他却反说'是人心本来就容易变'。\n当年唐明皇和杨贵妃在骊山华清宫，夜半私语；后来马嵬坡诀别，他为她作的《雨霖铃》曲里，全是泪。\n可即便如此，他仍比不上那个薄情的'锦衣郎'——因为人家当年，至少许过'比翼连枝'的愿。",
        "history": "纳兰性德（1655—1685），原名成德，字容若，是清朝大学士明珠的长子。他是康熙身边的御前侍卫、武艺高强、锦衣玉食，但终生为'情'所困——他娶了妻子卢氏，伉俪情深，可 1677 年卢氏难产而死，他写下几十首悼亡词。\n\n他 30 岁死于寒疾（一说抑郁而终），临死前几天还在写词。\n\n这首《木兰花》是他写给一位'有情人'的（有人说是初恋表妹，有人说是朋友顾贞观让他代笔，有人说是写自己与卢氏的'假设'）。\n\n'人生若只如初见'这七个字，是 21 世纪以来中国引用率最高的古诗名句之一——它几乎成了'所有感情的悼词'。",
        "appreciation": "纳兰性德最大的成就是'让'决绝''被听见——他不骂负心人，他只说'如果一开始就停留在最美的样子，多好'。\n\n'何事秋风悲画扇'——汉代班婕妤被冷落后，以'秋扇见捐'自比，扇子一入秋就被丢弃。纳兰用这个典故，让'扇子'承担'我被丢掉'。\n\n它教会我们：写'被辜负'，不要骂对方'负心'——找一个'看起来无关的物'（扇/灯/船/月），让它'被时间改变'，让'物的命运'承担'我的命运'。",
        "prompt": "选一段'关系变淡'的经历（朋友疏远/恋人分手/家人远去），找一个'看起来无关的物'（一把伞/一个杯子/一张旧车票），写它'被时间改变'的样子，让'物的命运'承担'这段关系的命运'。"
      },
      {
        "id": "cls-016",
        "title": "黄鹤楼",
        "poet": "崔颢",
        "era": "盛唐 · 约公元 730 年",
        "kind": "七言律诗 · 让李白搁笔之作",
        "tags": [
          "乡愁",
          "仙人已乘",
          "千古第一"
        ],
        "original": "昔人已乘黄鹤去，此地空余黄鹤楼。\n黄鹤一去不复返，白云千载空悠悠。\n晴川历历汉阳树，芳草萋萋鹦鹉洲。\n日暮乡关何处是？烟波江上使人愁。",
        "translation": "从前那位仙人已经乘着黄鹤飞走了，这里只空留下一座黄鹤楼。\n黄鹤一去就再也没回来，千百年来只有白云在此悠悠飘荡。\n晴天里汉阳那边的树木清晰可见，鹦鹉洲上的芳草茂盛浓密。\n日暮时分，我的故乡在哪里呢？江上烟波浩渺，让人愁绪满怀。",
        "history": "崔颢（约 704—754），汴州（今河南开封）人。这首《黄鹤楼》写于他漫游江南、登上武昌黄鹤楼时。\n\n最传奇的'典故'在李白——他晚年登黄鹤楼，本想题诗一首，看到崔颢这首，感叹'眼前有景道不得，崔颢题诗在上头'，搁笔而去。这就是'崔颢题诗，李白搁笔'的典故。\n\n李白后来不服气，写了《登金陵凤凰台》《鹦鹉洲》想'对打'，但都比不过这首。它被严羽《沧浪诗话》评为'唐人七律第一'。\n\n黄鹤楼始建于三国吴黄武二年（223），原址在武昌蛇山，相传仙人子安乘黄鹤过此，又说费祎登仙驾鹤于此。1700 多年间它被毁 7 次、重建 10 次，现在看到的楼是 1985 年重建的。",
        "appreciation": "这首诗最妙的是'空'——'此地空余黄鹤楼'、'白云千载空悠悠'、'烟波江上使人愁'——三个'空'字/类似'空'的意境，把'在'写成了'不在'。他在'在场'里写'缺席'，让一种'想当年'的惆怅蔓延。\n\n'日暮乡关何处是'——他没有说'我的家乡在 X'，他问'哪里是'。这种'反向提问'让'乡愁'更具体：你不知道'家'在哪，才是真的乡愁。\n\n它教会我们：写'思念'，不要写'我想家'，问'家在哪里'——让'我也在找'承担'我也在想'。",
        "prompt": "选一个你'回不去'的地方（故乡/老屋/旧校/一段过去），不写'我想回去'，只问'它还在吗'/'它变成什么样了'。让'寻找'承担'思念'。"
      },
      {
        "id": "cls-017",
        "title": "蜀道难",
        "poet": "李白",
        "era": "盛唐 · 约公元 742—744 年",
        "kind": "七言歌行 · 浪漫主义巅峰",
        "tags": [
          "蜀道",
          "奇险",
          "君臣入蜀"
        ],
        "original": "噫吁嚱，危乎高哉！蜀道之难，难于上青天！\n蚕丛及鱼凫，开国何茫然！\n尔来四万八千岁，不与秦塞通人烟。\n……\n剑阁峥嵘而崔嵬，一夫当关，万夫莫开。\n……\n锦城虽云乐，不如早还家。",
        "translation": "哎呀呀，多么高峻！多么危险！蜀道之难，比登上青天还难！\n蚕丛和鱼凫（古蜀国的两位国王），他们开国的历史多么渺茫！\n自从那时以来四万八千年，蜀地与秦地不曾有任何人往来。\n……\n剑阁关险峻而高大，一人在此把关，万人也打不开。\n……\n锦城（成都）虽然号称乐土，还是不如早些回家。",
        "history": "李白（701—762），字太白，号青莲居士，是盛唐最伟大的浪漫主义诗人。公元 742 年他被召入长安供奉翰林，本想'济苍生、安社稷'，却被唐玄宗当作'文学弄臣'——让他写'云想衣裳花想容'给杨贵妃作歌词。\n\n742—744 年，他终于被'赐金放还'（给一笔钱让你走），离开长安。他从长安南下，到四川送友人入蜀，写下这首《蜀道难》。\n\n关于这首诗的主旨，200 年来有 4 种说法：1）'严夫子入蜀'说（送朋友入蜀）；2）'讽玄宗入蜀'说（玄宗后来真在安史之乱中逃入蜀，李白可能预言了）；3）'蜀地险要，应慎用将'说；4）'仕途坎坷之喻'说。\n\n无论哪一种，李白用'蜀道'的'难'，写'人活着'的'难'。贺知章读后惊叹'谪仙人'——你是被贬下凡的仙人吧！",
        "appreciation": "李白是'语气'的发明家——'噫吁嚱，危乎高哉！'——这是中国诗里第一次'发出声音'：他不写'蜀道难'，他'喊'出来。这种'把'难'变成声音'的写法，让每个字都像从肺里挤出来。\n\n'一夫当关，万夫莫开'——他写'险'，不写'多高多陡'，写'一个人能挡一万人'。这是李白式的'以少胜多'。\n\n最后'锦城虽云乐，不如早还家'——他承认'蜀地有乐'，但他拒绝'因为有乐就留下'。这是一种'有'和'归'的决断。\n\n它教会我们：写'难'，不要写'我有多难'，把'难'变成'声音'（叹/喊/惊），让读者'听'到你的难。",
        "prompt": "写你'走过的最难的一段路'（事业/感情/学业/搬家/转行），不写'我有多难'，把'难'变成声音——选三个'叹词/惊词'（'哎'/'天哪'/'怎么会'），让每个叹词后面跟一个'具体画面'。"
      },
      {
        "id": "cls-018",
        "title": "己亥杂诗（其五）",
        "poet": "龚自珍",
        "era": "清 · 公元 1839 年",
        "kind": "七言绝句 · 近代启蒙先声",
        "tags": [
          "落红",
          "春泥",
          "人才"
        ],
        "original": "浩荡离愁白日斜，吟鞭东指即天涯。\n落红不是无情物，化作春泥更护花。",
        "translation": "满怀离愁，面对着西下的夕阳；甩响马鞭，向东一指，从此便是天涯。\n那凋落的花瓣，并不是无情的事物——它化作春泥，会去呵护新生的花朵。",
        "history": "龚自珍（1792—1841），浙江仁和（今杭州）人，是近代中国'启蒙思想'的先驱。他 27 岁中举、38 岁中进士，但一直做小官，因为敢说真话被排挤。\n\n公元 1839 年，他 48 岁，辞官离开北京回杭州。这年是中国农历'己亥年'。他一路南行 9000 里、走了 90 天，写下 315 首《己亥杂诗》——这是中国诗史上最大规模的一次'辞职后写诗'。\n\n这一年，也是林则徐被派往广东禁烟的那一年——中国近代史的'大门'即将被鸦片战争撞开。龚自珍在诗里写的'落红/春泥'，其实是在写'我这一代知识分子，虽然被排挤/凋零了，但我们要做下一代的养料'。\n\n'我劝天公重抖擞，不拘一格降人才'（《己亥杂诗·其一二五》）——他最著名的句子，是写给清朝皇帝的：'请让各种各样的人才都出来吧'。这句话在 1977 年恢复高考时，被无数人引用。",
        "appreciation": "'落红不是无情物，化作春泥更护花'——这是中国'奉献'主题最诗意的表达。他不写'我愿意牺牲'，他写'凋落的花依然有情——它变成春泥去护新花'。这是一种'转身'：'我'虽然不再是你眼前的'花'，但'我'会变成滋养下一代的'泥'。\n\n它教会我们：写'告别/退场'，不要写'我走了'，要写'我会变成另一种东西回来'。让'转身'承担'离去'。",
        "prompt": "写一段'你正在退出/已经退出一段关系/一份工作/一个身份'的经历，不写'我走了'/'我累了'，只写'我会变成 X'（一种养料/一个台阶/一束光/一段记忆），让'转身'承担'离去'。"
      }
