        "event": "1905 年爱因斯坦的「奇迹年」：用光量子假说解释光电效应（获 1921 年诺贝尔奖）、用分子运动论解释布朗运动、提出狭义相对论（E=mc²、时间膨胀、长度收缩）、以及博士论文。1915 年在柏林完成广义相对论：引力是时空弯曲，几何 + 物质 = 宇宙。1919 年英国天文学家爱丁顿在日全食中观测到星光被太阳引力弯曲，与爱因斯坦预言高度吻合，相对论一夜成名。",
        "impact": "相对论不仅是物理学革命，它让人类重新理解「时间不是绝对的、空间不是空无一物的容器」。没有广义相对论就没有 GPS 全球定位系统（卫星时钟需校准相对论效应）。它和量子力学一起，构成 20 世纪所有高技术（核能、半导体、激光、互联网）的理论基础。爱因斯坦那句「想象力比知识更重要」也成为科学时代的精神宣言。",
