      "title": "No.214 寻找同类：小红书、bilibili，以及五花八门的那些社区 | 中国互联网故事 26",
      "desc": "本期由 网易UU远程 赞助播出\n网易UU远程「真4K、真免费、真好用」，无论是 AI coding 还是远程办公都出色，万千用户的口碑推荐：https://uuyc.163.com/?source_channel=brand_broadcast1\n主播 | 刘飞 潇磊\n移动互联网这些年，绝大多数曾经热闹的社区都慢慢消失了。论坛关了，垂直社区没人去了，连很多大厂砸钱做出来的产品，也没能留下多少痕迹。\n但有两个例外。一个从海外购物攻略起家，最后成了很多年轻人的搜索引擎；一个原本只是 A 站宕机时的“备用网站”，后来却装下了中国年轻人的动漫、游戏、知识、生活和无数奇奇怪怪的爱好。\n更有意思的是，最擅长吞噬用户时间的字节跳动，这么多年一直想做社区，却始终没能真正吃掉它们。\n为什么社区这种看起来最容易模仿的产品，反而可能是互联网里最难复制的东西？\n这一期，我们继续寻找中文互联网里的“同类”。\n来杯半拿铁，咱们边喝边唠。\n——\n\n—\n潇磊、刘飞的声音已授权给豆包、剪映等字节系产品使用若干年。\n在视频平台看到的无真人出镜、用我们的音色生成的 AI 内容，均非我们制作。\n—\n半拿铁也开始讲时事了： 半拿铁·周刊 \n半拿铁也开始讲故事了： 半拿铁·故事篇 \n�听友投稿邮箱：bannatie@163.com\n️杭州特调「芝麻·半拿铁」的品尝地：西湖区华星路 【01coffee】\n️上海特调「米乳·半拿铁」的品尝地：前滩公园巷 【彼屯 between 自然商店】\n�半拿铁周边购买淘宝店：小羊商店Sheepedia\n� 半拿铁全新周边：《人工智能风云录》纸质书，可在各大电商平台购买。天猫店铺目前为 5 折\n——\n时间轴：\n10:03 从海外购物攻略起步：毛文超、瞿芳与小红书的创业开端\n24:53 口碑平台还是内容社区？一次产品分歧决定“笔记”的未来\n35:41 电商遇阻后的关键抉择：榨取社区流量，还是回归社区本身\n43:41 治理危机之后迎来增长：小红书从女性购物走向生活方式社区\n01:04:13 从种草平台到生活搜索入口：真实经验如何成为信息基础设施\n01:10:01 从 Niconico、A站到B站：中国弹幕社区的早期源流\n01:20:23 从爱好者社团到商业公司：陈睿加入与B站的关键转向\n01:28:23 合法化、正版化、商业化：B站活下来的路径与“不加贴片”承诺\n01:49:42 贴片广告大辩论：社区体验、创作者收入与商业效率之辩\n02:07:19 其他社区的不同命运：糗事百科、TapTap、Keep、LOFTER与脉脉\n02:31:51 即刻社区转型与小宇宙崛起：时间戳评论如何让播客“聊起来”\n02:40:41 垂直社区消失之后：商业化、破圈诅咒与“找到同类”的永恒需求\n02:48:44 读评论彩蛋环节\n\n重要时间线\n2007 年 \nAcFun（A站）上线，后来引入弹幕，成为中国最早的重要二次元社区之一。\n2009 年 \nA站内部动荡、频繁宕机。用户徐逸搭建 MikuFans，后来改名为 Bilibili。\n2011 年 \n陈睿主动联系徐逸并投资 B站，B站开始从爱好者网站逐渐转向正规商业公司。\n2013 年 \n毛文超与瞿芳创业，最初制作《小红书出境购物攻略》PDF，随后上线小红书 App。\n2014 年 \n陈睿全职加入 B站并担任董事长兼 CEO，开始推动“合法化、正版化、商业化”。\n同年底，小红书上线自营跨境电商“福利社”。\n2016 年 \nB站因番剧贴片广告引发用户反弹，陈睿重申“不做贴片广告”，留下“B站未来有可能会倒闭，但绝不会变质”的说法。\n同年，《Fate/Grand Order》上线，游戏开始成为 B站最重要的收入来源。\n2017 年 \n小红书电商增长陷入瓶颈，公司开始重新思考电商与社区的关系，最终决定把社区放回核心位置。\n这一时期，B站游戏收入占比超过八成。\n2018 年 \n小红书通过《偶像练习生》《创造101》等综艺第一次大规模破圈。\n3 月，B站登陆纳斯达克。\n同年，陷入长期经营危机的 A站被快手收购。\n2019 年 \n小红书日活突破千万，但随后因违规医美、软广等问题被应用商店下架整改。\n年底，B站首届跨年晚会大获成功，品牌进一步走出二次元圈层。\n2020 年 \nB站推出《后浪》等“破圈”内容，知识、财经、科技、生活等品类快速增长。\n疫情期间，小红书也从美妆购物社区迅速扩展到菜谱、装修、家居、健身等生活方式内容，并大力发展视频。\n2021 年 \n小红书日活突破5000万，成为中国最大的社区之一，并开始成为抖音重点研究和竞争的对象。\n3 月，B站在香港二次上市。\n同年，小宇宙逐渐成为中文播客社区的重要代表。\n2022—2023 年 \nB站高速增长阶段结束，战略重点从扩大用户规模转向盈利和商业效率。\n小红书则继续寻找电商模",
