      "desc": "本期主播：刘旸教主\n本期嘉宾：《喜剧之王单口季》卡司 贤鱼 \n本期我们请到了贤鱼，来安安静静（吗？）、文质彬彬、端庄优雅地坐下来好好聊聊自己的来时路，本期包含以下内容——\n-贤鱼编年史？咱喜剧演员也是整上参考文献了！\n-第一轮为什么选了花呗这个段子？\n-上一次上节目被淘汰，这次重新参加节目、重新见到观众是什么感受？\n-金牌战没人挑战，当时的感受——侥幸\n-节目播出之后，收到了免费吃饭的邀约？\n-收到爸爸的鼓励和肯定：太！爽！了！\n-年薪25万，西湖买不下来，西葫芦倒是可以买下来呀！\n-从医学到银行到单口喜剧的来时路\n-来上海的三大诱惑：包子、板面和米饭？？？来上海的两大恩人：父母和老崔\n-教主看贤鱼的“喜剧播客养成系变化”：量变+刻意练习=质变\n-教主：你说你是根据谁学成现在这样的？给我说清楚！美国人太坏了！\n-“如果播客现在是你唯一的救命稻草、唯一能让大家认识你的渠道，你就应该把你这辈子最好的段子在播客里讲。”\n-贤鱼：我有时候跟别的 ENFP 在一块，我就觉得他挺吵的。教主：？？？？？？？\n-做播客，做主持和纯嘉宾有什么不一样的感受？\n-奇妙缘分：贤鱼最开始学单口的老师是六兽？第一次录播客就是无聊斋衡水中学？\n-参加节目后收到的印象深刻的repo？\n-单口喜剧和播客对贤鱼来说分别意味着什么？\n-贤鱼从小就喜欢搞笑：学春晚小品、参加衡水老白干的年会、入选衡水文艺团\n-聊聊最开始讲单口的经历\n-上线上节目，对贤鱼来说意味着什么？\n欢迎收听本期播客！\n\n【关于我们】\n🎬收看无聊斋视频内容？关注微博、小红书、B站、抖音：@无聊斋\n🙋投稿成为无聊斋嘉宾？公众号关注「无聊斋」回复“投稿”\n👀来参与线下录制？公众号关注「无聊斋」会有不定期观众招募掉落\n👗想加入无聊斋听友群？关注 @无聊斋 小红书，加入首页听友群\n🤝商务合作？欢迎发送邮件至 luckylikeu@163.com \n✍️制作：婧文\n✂️剪辑：小天",
