      "desc": "♾️ 大家好，欢迎来到「无人知晓」，我是孟岩。\n这期节目，我和李继刚聊了三个多小时。\n他有一个我很喜欢的判断：工业革命拿走了体力，AI 正在拿走脑力。 留给人的，是心力。 \n不是你知道什么，而是你想要什么。不是你能想出什么，而是你能感受到什么。\n我们聊了 AI 时代的阅读、表达和教育，聊了信息输入如何塑造一个人的命运。\n他从理性的尽头走向心灵，我从心灵出发走向结构，但所有话题，最终都指向同一个问题：\n人何以自处？ \n🔗 官网地址\n点此访问有知有行官网，获取完整文稿区内容。 \n💬 本期嘉宾\n李继刚\n🪡 时间戳\n04:15 道也好，真理也罢——我们每个人只是在拿着自己的取景框看它\n07:46 投资：现金只是筹码，换的是未来财富份额上升的可能性\n19:56 我隔一阵子就审视下那个问题： 人来世间走这一趟，到底干嘛来的？ \n22:13 求真：不为什么，只为「进一寸有进一寸的欢喜」\n31:12 我们同时活在三个世界里：原子世界、比特世界与向量世界\n46:45 表达，即存在\n57:40 干状态与湿状态：AI 时代，稀缺的是心力\n68:37 人机协作的两条路：一条通向异质性的增幅，一条通向思考的撤离 \n76:44 人类孟岩的反身之问：谁是谁的 agent？\n80:08 组织的长尾效应：互联网时代，公司是一张网；AI 时代，公司在打一口井\n96:00 若闲暇成为未来的时代处境，人迟早要回答一个问题：你往何处去？\n118:03 提示词是有形状的 \n129:19 &nbsp;所有的事情只要重复三次，我就要把它自动化\n146:52 如果德鲁克活在今天，他讨论的或许会是：一个人如何管理一万个 agents\n162:41 我只抓两个压舱石：1. 什么是不变的；2. 稀缺性转移到哪里了\n169:27 品味（taste）即权重：审美，是个人神经元被反复冲刷后的显影 \n172:27 回归线下、真正在场：彼此看见的交流，才是人与人相遇的意义所在\n183:08 Your feed is your fate. \n190:09 以前是水的教育，往脑子里灌；未来是火的教育，找那根小火柴\n201:50 终点：人，何以自处？ \n☁️ 猜你想搜\n嘉宾个人公众号： 李继刚 ，当中包含了嘉宾个人使用并公开分享出来的多个prompt、近期在读的论文以及他与AI共创的实践等诸多内容。\n以下按时间顺序排列 \n03:41 Reframing（重构） ：用新的视角重新看待同一件事，从而改变对它的理解、认知或感受。\n06:29 &nbsp;此处孟岩提及的「栅格理论」实为 格栅理论（Latticework of Mental Models） ：投资大师查理·芒格提出的思维方法。将多个学科的核心模型，像格栅一样组合在脑中，遇到问题时从多个角度同时分析，而非只用单一视角判断。\n10:28 《文明、现代化、价值投资与中国》：喜马拉雅资本创始人、查理·芒格家族资产管理者李录的理论文集。\n23:32 贝叶斯定理（Bayes’ theorem） ：一种概率公式，用已有信息更新对未来事件判断的方法。\n27:26 奥卡姆剃刀（Occam’s razor） ：14 世纪哲学原则，主张「如无必要，勿增实体」，即优先选择更简单的解释。\n28:41 万有理论（Theory of Everything） ：物理学中设想的终极统一公式，用来同时解释强力、弱力、电磁力与引力。\n31:46 向量（Vector）： 在数学中指既有方向又有大小的量，在 AI 中常指「用一组数字表示语义坐标」。\n34:08 马太效应（Matthew effect）： 出自《圣经·马太福音》，现代多指强者愈强、弱者愈弱的社会现象，资源、机会、声誉等往往会向已经占优势的人进一步集中，AI 从而形成「赢家通吃」的结构。\n因为凡有的，还要加给他，叫他有余；没有的，连他所有的也要夺过来。\nFor unto every one that hath shall be given, and he shall have abundance: but from him that hath not shall be taken away even that which he hath. 34:23 梅特卡夫定律（Metcalfe’s law） ：网络节点越多，网络整体价值增长越快。\n40:55 《世界是平的：一部二十一世纪简史》（The World Is Flat: A Brief History of the Twenty-first Century） ：托马斯·弗里德曼（Thomas L. Friedman） 2005 年的著作，认为全球化与互联网让距离成本大幅下降。\n43:53 圆桌讨论提示词 ： 点击链接获取 \n47:28 大他者（The Big Ot",
