      "show": "文化有限",
      "title": "Vol.348 一天：我很爱你，但已经不喜欢你了",
      "desc": "本期节目我们读小说《一天》，作者大卫·尼克斯。 \n\n《一天》出版于2009年， 出版后大获好评， 获当年《卫报》“年度图书”大奖及2010年英国小说榜冠军。2011年由作者改编的同名电影上映，安妮·海瑟薇主演。2024年，作者参与编剧并任执行制片人的同名电视剧由 Netflix制作播出。同名音乐剧于2026年首演。小说 故事跨越近20年时间 ， 聪慧狡黠、出身平凡的爱玛与俊美自恋的花花公子德克斯特原本像两道平行线，不会有任何交集。 大学毕业前夕的一天， 两人短暂邂逅，称不上甜蜜，却深深印入彼此心中最柔软的部分。 此后每年同一天，伦敦、罗马、巴黎、爱丁堡，时空变换， 他们焦灼、倾诉、挂念、幻想、安慰、伤害，总是在最需要彼此的时刻，一再错过 。 二十年追逐的尽头，是甘美的琼浆，还是苦涩的酸汁？ 如果早点懂得，幸福会不会更久一点？ \n\n大卫•尼克斯（1966-）， 英国著名编剧，畅销书作家。曾 从事音乐剧编剧、演员工作，后专职写作 。作品有《恋爱学分》《我们，一次旅行》《有你的夏天》等。 \n\n你会听到： \n1、介绍小说故事情节、作者、改编情况与时代背景。 \n2、分享阅读体验。如何看待爱玛与德克斯特之间的关系？爱玛对他的爱和等待“卑微”吗？ \n3、比较《一天》与《正常人》的异同，如果将自我代入小说，更倾向于选择哪种感情经历？ \n4、精彩片段分享。 \n5、横跨20年的故事中，如何体现时间的重量、价值和意义？有哪些启发？ \n\n片头曲：靛厂 \n片尾曲：Billy Bragg - St Swithin's Day \n\n主播：星光 / 超哥 / 大壹",
