      "full": "【开场】\n本期《不合时宜》带来「华人家庭这个巨兽，爱与剥削为何总是同时存在」。一档值得关注的播客。\n\n【本期内容叙述】\n本期《不合时宜》播出「华人家庭这个巨兽，爱与剥削为何总是同时存在」。节目延续一贯风格，围绕这一主题层层展开。\n▸ 2025 年，一位以公共报道著称的华人记者，突然把笔调转向了自己的家。\n▸ 记者谭蕙芸，曾在新闻业里追问外部世界的真相，教学生如何采访弱势社群。可她自己的家中，一直藏着一个不能言说的秘密。她的哥哥，那位被寄予最高期望的长子长孙，青少年时期被情绪问题困扰。全家从香港移民到加拿大后，在\"家丑不可外扬\"的家风影响下，未能\n▸ 她把这些经历，写成《家锁：华人家庭这个巨兽》一书。以女儿和记者的双重身份，她对这个被封存了三十年的家庭黑箱，做了一次诚实的勘探。书名里的\"家锁\"是个双关：家庭既是庇护，也是一把锁。\n▸ 我们的对话从这本书开始，聊到的却远不止一个家庭。为什么华人父母宁可把患病的孩子藏起来，也不愿让外人看见\"不完美\"？为什么\"孝\"字之下，连好好哭一场的空间都没有？移民海外真的是解药吗，还是说，个人主义的自由恰恰让一个不懂求助的人滑向了流浪的边\n▸ 谭蕙芸谈到照护者如何在爱与内疚里几近崩塌，谈到\"与其买包，不如拿去做心理咨询\"这句在东亚社会仍显奢侈的话，也谈到写作本身如何成了疗愈。当她终于请人一起打开哥哥尘封的画作，一个曾被简化为\"疾病\"的人，重新成了有名字、有才华、值得尊重的个体，甚\n▸ 这不只是一个家庭的创伤叙事，而是对整个东亚亲密关系底层逻辑的追问。家庭从来不只是私人的事，它是我们检验一个社会有没有公义的第一现场。\n▸ 谭蕙芸（Vivian Tam） ：资深传媒人，香港中文大学新闻与传播学院讲师\n▸ 在外界看来模范的移民华人家庭，一直将患有精神疾病的哥哥“藏起来”\n\n节目没有停留在表面的观点罗列，而是在具体的情境、对话与追问中，把话题真正推进到深处。\n\n【🗣️ 经典对话】\n这一期里，有些话值得反复听：\n\n“与其买包，不如拿去做心理咨询”\n“母女和解文学中难以逾越的高峰”\n“让人心碎的故事，聚焦理解心理疾病的多层面的重要性，尤其是亚裔社群中”\n\n【深度解读】\n本期主题：「华人家庭这个巨兽，爱与剥削为何总是同时存在」。本期主题：「华人家庭这个巨兽，爱与剥削为何总是同时存在」。本期《不合时宜》围绕「华人家庭这个巨兽，爱与剥削为何总是同时存在」展开。一档值得关注的播客，延续节目一贯的深度与质感。\n\n【核心看点】\n• 当期重点：2025 年，一位以公共报道著称的华人记者，突然把笔调转向了自己的家。记者谭蕙芸，曾在新闻业里追问外部世界的真相，教学生如何采访弱势社群。\n\n【为什么值得听】\n延续《不合时宜》一贯的内容水准，值得点开收听完整内容。\n\n【结尾】\n延续《不合时宜》一贯的内容水准，值得点开收听完整内容。",
